import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Storage Backends and Paths","description":"SQLite versus PostgreSQL, browser storage, per-module storage paths, and how this compares with editors such as Zed.","frontmatter":{"sidebarTitle":"Storage Backends and Paths","icon":"hard-drive","title":"Storage Backends and Paths","description":"SQLite versus PostgreSQL, browser storage, per-module storage paths, and how this compares with editors such as Zed.","summary":"Compares SQLite, PostgreSQL, and browser storage by deployment and use, and relates persistent state to user-owned storage locations. It explains context-derived Module paths and the storage facade, then gives exploratory criteria for deciding when to switch backends.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":2,"status":"Exploring","tags":["feluqa","storage","postgresql","sqlite","paths"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"feluqa.rs/storage/storage-backends-and-paths.md","filePath":"feluqa.rs/storage/storage-backends-and-paths.md"}'),o={name:"feluqa.rs/storage/storage-backends-and-paths.md"};function d(n,e,i,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="storage-backends-and-paths" tabindex="-1">Storage Backends and Paths <a class="header-anchor" href="#storage-backends-and-paths" aria-label="Permalink to &quot;Storage Backends and Paths&quot;">​</a></h1><p>SQLite can serve as storage for Feluqa apps, as some editors do for local data. The right choice depends on <strong>where the application runs and how it is used</strong>.</p><table tabindex="0"><thead><tr><th>Deployment</th><th>Recommended store</th><th>Notes</th></tr></thead><tbody><tr><td>Hosted app, shared data, several users</td><td><strong>PostgreSQL</strong></td><td>Natural choice for multi-user business data.</td></tr><tr><td>Small installation on one server</td><td>SQLite</td><td>Acceptable while concurrent writes and availability needs stay modest.</td></tr><tr><td>Local workstation app</td><td><strong>SQLite</strong> in the user&#39;s data directory</td><td>With migrations and backups.</td></tr><tr><td>Browser UI</td><td>Server stays the source of truth</td><td><code>localStorage</code> for simple preferences, IndexedDB for structured offline data. These are per-browser and never replace the server database.</td></tr></tbody></table><p>The model resembles Zed&#39;s: editable settings in files, persistent state in a database, in a location owned by the user. Zed keeps user settings in JSON files with comments and workspace data (recent projects, tabs, panes) in SQLite databases in its user data directory (<a href="https://zed.dev/docs/configuring-zed" target="_blank" rel="noreferrer">Zed settings</a>, <a href="https://zed.dev/docs/troubleshooting" target="_blank" rel="noreferrer">Zed troubleshooting</a>). Browser storage behavior is described in <a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Client-side_APIs/Client-side_storage" target="_blank" rel="noreferrer">MDN client-side storage</a>.</p><blockquote><p>The exact criteria for switching from SQLite to PostgreSQL are still to be defined in the architecture.</p></blockquote><h2 id="storage-paths" tabindex="-1">Storage paths <a class="header-anchor" href="#storage-paths" aria-label="Permalink to &quot;Storage paths&quot;">​</a></h2><p>Storage is resolved from the context, never guessed:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;product-or-platform&gt;/storage/modules/&lt;module-id&gt;[/&lt;submodule&gt;]</span></span></code></pre></div><p>Accessed through the facade <code>feluqa::storage_path()</code> or <code>ctx.storage()</code>. A crate without a module owner is an error.</p><h2 id="proposed-switch-criteria-exploring" tabindex="-1">Proposed switch criteria (exploring) <a class="header-anchor" href="#proposed-switch-criteria-exploring" aria-label="Permalink to &quot;Proposed switch criteria (exploring)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Signal</th><th>Move toward PostgreSQL</th></tr></thead><tbody><tr><td>More than one app node</td><td>yes</td></tr><tr><td>Sustained concurrent writers</td><td>yes</td></tr><tr><td>High-availability or replication requirement</td><td>yes</td></tr><tr><td>Single node, single site, low write concurrency</td><td>stay on SQLite</td></tr><tr><td>Air-gapped or field deployment with no DB admin</td><td>stay on SQLite</td></tr></tbody></table>',11)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
